from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.7, 'crossover': 0.9, 'exploration': 0.45, 'local_fraction': 0.25, 'radius': 0.15, 'population': 30, 'generations': 8, 'reason': 'With only 24 of 100 evaluations used and 12 stagnant steps at zero recent improvement, the optimizer needs more exploration while remaining sample-efficient. Auto surrogate lets held-out RMSE pick RBF vs quadratic given the 10-D space and small dataset. current_to_best balances convergence toward the incumbent with diversity in DE. Moderate mutation (0.7) and high crossover (0.9) give good mixing; exploration 0.45 adds novelty pressure to escape stagnation; local_fraction 0.25 with radius 0.15 focuses some effort near promising regions. Population 30 and 8 generations keep candidate generation cheap relative to remaining budget without overspending.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
